{
  "measure_id": "MEAS-F8CD0BB9",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Bans any person from demonstrating within 100 feet of the entrance to an abortion facility during its operating hours."
    }
  ],
  "findings": [
    {
      "id": "f1",
      "clause_id": "§1",
      "concern_id": "C24",
      "effect": "costs",
      "direction": null,
      "quote": "No person may demonstrate within 100 feet of the entrance of a facility that provides abortion services during its hours of operation.",
      "mechanism": "Restricts speech by prohibiting demonstrations within a 100-foot radius of specific facility entrances during business hours.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Current law allows demonstrations on public sidewalks subject only to general noise and traffic rules. The measure changes this by strictly prohibiting all demonstrations within 100 feet of an abortion facility entrance during its hours of operation.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q2",
      "answer": "Protesters face an opportunity cost of losing their preferred, proximate location to communicate their message to patients. Local governments may incur minor administrative and enforcement costs to mark the 100-foot boundaries and respond to violations.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "Protesters and advocates who wish to demonstrate near these facilities bear the cost of restricted location access. Patients, staff, and the abortion facilities themselves benefit from reduced exposure to demonstrations immediately outside the entrance.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Protesters will likely relocate their demonstrations to just outside the 100-foot boundary, potentially utilizing louder amplification methods or changing their tactics. Law enforcement will need to measure the perimeters and establish protocols for clearing the zone during clinic hours.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "Addresses the problem of patients and staff facing potential obstruction, noise, or intimidation when entering abortion facilities. The mechanism imposes a fixed 100-foot buffer zone where all demonstrations are banned during operating hours, ensuring an unobstructed entry. However, this creates a new restriction on speech in traditional public forums.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "Law enforcement agencies gain discretion to determine what constitutes a 'demonstration' and the power to clear the 100-foot perimeter. Abortion facilities gain the concentrated benefit of a demonstration-free zone immediately surrounding their entrances.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "It is disputed whether fixed buffer zones effectively improve patient access and safety, or whether they merely displace the conflict to the edge of the zone. Additionally, legal scholars disagree on whether such specific restrictions can be enforced without unconstitutionally burdening protected First Amendment speech.",
      "disputed": true
    },
    {
      "clause_id": "§1",
      "question_id": "Q8",
      "answer": "Local law enforcement will expend resources to measure the 100-foot zones, educate the public, and respond to calls, though this might be offset by spending less time managing direct conflicts right at clinic doors.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q9",
      "answer": "This is a statutory change that can be undone by subsequent legislation, or potentially struck down by courts if found to violate constitutional speech protections.",
      "disputed": false
    }
  ],
  "flags": [
